import base64
import binascii
import json
import re
import tarfile
import tempfile
from logging import getLogger

logger = getLogger(__name__)

#: Manifest fields copied from a package's own ``package.json`` into the registry
#: document. A client resolving a dependency tree reads them from here rather than
#: from the tarball, which it has not downloaded yet -- omitting them makes an
#: install silently skip the package's dependencies. Restricted to an explicit
#: allow-list so a package cannot inject arbitrary keys (notably ``dist``, which
#: is generated by the content handler and must not be attacker-controlled).
PACKUMENT_MANIFEST_FIELDS = (
    "description",
    "license",
    "main",
    "type",
    "bin",
    "directories",
    "scripts",
    "engines",
    "os",
    "cpu",
    "libc",
    "dependencies",
    "devDependencies",
    "peerDependencies",
    "peerDependenciesMeta",
    "optionalDependencies",
    "bundleDependencies",
    "bundledDependencies",
    "exports",
    "dependenciesMeta",
    "deprecated",
    "hasInstallScript",
)

# Bounds applied before a manifest is stored. The values are deliberately
# generous for real packages but keep a hostile publish or upstream document
# from filling the database with arbitrary JSON.
MANIFEST_MAX_BYTES = 256 * 1024
MANIFEST_MAX_STRING = 4096
MANIFEST_MAX_KEY = 214
MANIFEST_MAX_MAP_ENTRIES = 2000
MANIFEST_MAX_ARRAY_ENTRIES = 100
MAX_PACKAGE_JSON_BYTES = 1024 * 1024
MAX_TAR_MEMBERS = 10000

_SCALAR_FIELDS = {"description", "license", "main", "type", "deprecated"}
_MAP_FIELDS = {
    "dependencies",
    "devDependencies",
    "peerDependencies",
    "optionalDependencies",
    "scripts",
    "engines",
}
_ARRAY_FIELDS = {"os", "cpu", "libc"}
_BUNDLE_FIELDS = {"bundleDependencies", "bundledDependencies"}
_JSON_FIELDS = {"exports", "dependenciesMeta"}
_LIFECYCLE_SCRIPTS = ("preinstall", "install", "postinstall")
_JSON_MAX_DEPTH = 4


def urlpath_sanitize(*args):
    """
    Join an arbitrary number of strings into a /-separated path.

    Replaces uses of urljoin() that don't want/need urljoin's subtle semantics.

    Returns: single string provided arguments separated by single-slashes

    Args:
        Arbitrary list of arguments to be join()ed
    """
    segments = []
    for a in args + ("",):
        stripped = a.strip("/")
        if stripped:
            segments.append(stripped)
    return "/".join(segments)


def extract_package_info(relative_path):
    """
    Tries to extract the name and the version of a package
    from the relative path string.

    Args:
        The relative_path string. "package/-/package-version.tgz"
    """
    pattern = r"^(?P<name>@?[^/]+(?:/[^/]+)?)(?:/-/(?P<base_name>[^/]+?)-(?P<version>\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?)\.tgz)?$"
    match = re.match(pattern, relative_path)

    if match:
        name = match.group("name")
        version = match.group("version")
        return name, version
    else:
        return None, None


def _clean_string(value):
    """Return a bounded, NUL-free string, or None if the value is invalid."""
    if not isinstance(value, str) or not value or len(value) > MANIFEST_MAX_STRING:
        return None
    if "\x00" in value:
        return None
    return value


def _clean_key(value):
    if not isinstance(value, str) or not value or len(value) > MANIFEST_MAX_KEY:
        return None
    if "\x00" in value:
        return None
    return value


def _clean_path(value):
    """Validate a path from ``bin``/``directories``, rejecting escapes."""
    path = _clean_string(value)
    if path is None:
        return None
    if path.startswith(("/", "\\")):
        return None
    if any(part == ".." for part in path.replace("\\", "/").split("/")):
        return None
    return path


def _clean_string_map(value):
    if not isinstance(value, dict) or len(value) > MANIFEST_MAX_MAP_ENTRIES:
        return None
    cleaned = {}
    for key, item in value.items():
        key = _clean_key(key)
        item = _clean_string(item)
        if key is None or item is None:
            return None
        cleaned[key] = item
    return cleaned


def _clean_path_map(value):
    if not isinstance(value, dict) or len(value) > MANIFEST_MAX_MAP_ENTRIES:
        return None
    cleaned = {}
    for key, item in value.items():
        key = _clean_key(key)
        item = _clean_path(item)
        if key is None or item is None:
            return None
        cleaned[key] = item
    return cleaned


def _clean_bin(value):
    # ``package.json`` permits a string form, while registry metadata usually
    # uses an object. Keep both, validating the path either way.
    if isinstance(value, str):
        return _clean_path(value)
    return _clean_path_map(value)


def _clean_directories(value):
    return _clean_path_map(value)


def _clean_array(value):
    if not isinstance(value, list) or len(value) > MANIFEST_MAX_ARRAY_ENTRIES:
        return None
    cleaned = []
    for item in value:
        item = _clean_string(item)
        if item is None:
            return None
        cleaned.append(item)
    return cleaned


def _clean_peer_dependencies_meta(value):
    if not isinstance(value, dict) or len(value) > MANIFEST_MAX_MAP_ENTRIES:
        return None
    cleaned = {}
    for key, item in value.items():
        key = _clean_key(key)
        if key is None or not isinstance(item, dict):
            return None
        meta = {}
        for meta_key, meta_value in item.items():
            if not isinstance(meta_key, str) or len(meta_key) > MANIFEST_MAX_KEY:
                return None
            if isinstance(meta_value, str):
                meta_value = _clean_string(meta_value)
                if meta_value is None:
                    return None
            elif not isinstance(meta_value, bool):
                return None
            meta[meta_key] = meta_value
        cleaned[key] = meta
    return cleaned


def _clean_bundle(value, manifest):
    # ``bundleDependencies: true`` means "all dependencies"; expand it so the
    # stored value is explicit and clients do not have to interpret the flag.
    if value is True:
        dependencies = manifest.get("dependencies")
        if not isinstance(dependencies, dict):
            return None
        return _clean_array(list(dependencies.keys()))
    return _clean_array(value)


def _clean_json(value, depth=0):
    """Validate a bounded, generic JSON value (``exports``, ``dependenciesMeta``)."""
    if depth > _JSON_MAX_DEPTH:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, str):
        return _clean_string(value)
    if isinstance(value, list):
        if len(value) > MANIFEST_MAX_ARRAY_ENTRIES:
            return None
        cleaned = []
        for item in value:
            item = _clean_json(item, depth + 1)
            if item is None:
                return None
            cleaned.append(item)
        return cleaned
    if isinstance(value, dict):
        if len(value) > MANIFEST_MAX_MAP_ENTRIES:
            return None
        cleaned = {}
        for key, item in value.items():
            key = _clean_key(key)
            if key is None:
                return None
            item = _clean_json(item, depth + 1)
            if item is None:
                return None
            cleaned[key] = item
        return cleaned
    return None


def has_install_script(manifest):
    """Return whether a manifest declares an install lifecycle script."""
    scripts = manifest.get("scripts")
    if not isinstance(scripts, dict):
        return False
    return any(script in scripts for script in _LIFECYCLE_SCRIPTS)


_SRI_ALGORITHMS = {"sha256": 32, "sha384": 48, "sha512": 64}
_SRI_PREFERENCE = {"sha256": 1, "sha384": 2, "sha512": 3}
_SHA1_RE = re.compile(r"^[0-9a-f]{40}$")


def sri_from_artifact(artifact):
    """Return the sha512 SRI string for a stored artifact, or None."""
    sha512 = getattr(artifact, "sha512", None)
    if not sha512:
        return None
    try:
        digest = bytes.fromhex(sha512)
    except ValueError:
        return None
    if len(digest) != _SRI_ALGORITHMS["sha512"]:
        return None
    return "sha512-" + base64.b64encode(digest).decode("ascii")


def parse_sri(value):
    """
    Parse one or more SRI tokens and return ``(algorithm, hex_digest)``.

    Returns the strongest valid token, or None when no token is valid.
    """
    if not isinstance(value, str):
        return None

    candidates = []
    for token in value.strip().split():
        algorithm, separator, digest = token.partition("-")
        if not separator or algorithm not in _SRI_ALGORITHMS:
            continue
        try:
            raw = base64.b64decode(digest, validate=True)
        except (binascii.Error, ValueError):
            continue
        if len(raw) != _SRI_ALGORITHMS[algorithm]:
            continue
        candidates.append((algorithm, raw.hex()))

    if not candidates:
        return None
    return max(candidates, key=lambda candidate: _SRI_PREFERENCE[candidate[0]])


def parse_shasum(value):
    """Return a normalized sha1 hex digest, or None when it is invalid."""
    if not isinstance(value, str):
        return None
    value = value.strip().lower()
    return value if _SHA1_RE.fullmatch(value) else None


def validate_upstream_integrity(dist):
    """
    Return validated ``(integrity, shasum)`` values from an upstream ``dist``.

    ``integrity`` is normalized to a single SRI token; ``shasum`` is a sha1 hex
    digest. Invalid values are dropped rather than trusted.
    """
    if not isinstance(dist, dict):
        return None, None

    integrity = None
    parsed = parse_sri(dist.get("integrity"))
    if parsed:
        algorithm, digest = parsed
        integrity = f"{algorithm}-{base64.b64encode(bytes.fromhex(digest)).decode('ascii')}"

    return integrity, parse_shasum(dist.get("shasum"))


def sanitize_manifest(manifest, *, strict=False):
    """
    Return a bounded, allow-listed copy of an npm ``package.json``.

    The registry document must never carry publisher-chosen keys (notably
    ``dist``) and the database must not store unbounded JSON. Invalid fields are
    dropped; when ``strict`` is set, a non-object manifest or one that exceeds
    the size cap raises ``ValueError`` so callers can reject the request.

    Args:
        manifest: The decoded ``package.json`` (or an upstream version entry).
        strict: Raise instead of falling back for an unusable manifest.

    Returns:
        dict: The sanitized manifest.
    """
    if not isinstance(manifest, dict):
        if strict:
            raise ValueError("package manifest must be a JSON object")
        return {}

    result = {}
    for field in PACKUMENT_MANIFEST_FIELDS:
        if field not in manifest:
            continue

        value = manifest[field]
        if field in _SCALAR_FIELDS:
            cleaned = _clean_string(value)
        elif field in _MAP_FIELDS:
            cleaned = _clean_string_map(value)
        elif field == "bin":
            cleaned = _clean_bin(value)
        elif field == "directories":
            cleaned = _clean_directories(value)
        elif field == "peerDependenciesMeta":
            cleaned = _clean_peer_dependencies_meta(value)
        elif field in _ARRAY_FIELDS:
            cleaned = _clean_array(value)
        elif field in _BUNDLE_FIELDS:
            cleaned = _clean_bundle(value, manifest)
        elif field in _JSON_FIELDS:
            cleaned = _clean_json(value)
        elif field == "hasInstallScript":
            cleaned = value if isinstance(value, bool) else None
        else:  # pragma: no cover - defensive: keep the allow-list authoritative
            cleaned = None

        if cleaned is None:
            logger.debug("Dropping invalid npm manifest field %r", field)
            continue
        result[field] = cleaned

    # ``hasInstallScript`` is a registry-generated field; derive it from the
    # lifecycle scripts whenever scripts are present so it cannot be spoofed.
    if "scripts" in result:
        result["hasInstallScript"] = has_install_script(result)

    # npm accepts ``directories.bin`` as an alternative to ``bin``. Normalize it
    # so clients see one consistent key.
    if "bin" not in result:
        directories = result.get("directories")
        if isinstance(directories, dict):
            directories_bin = _clean_path(directories.get("bin"))
            if directories_bin is not None:
                result["bin"] = directories_bin

    encoded = json.dumps(result, separators=(",", ":")).encode("utf-8")
    if len(encoded) > MANIFEST_MAX_BYTES:
        if strict:
            raise ValueError("package manifest exceeds the maximum allowed size")
        logger.warning(
            "Dropping npm manifest: serialized size %s exceeds %s bytes",
            len(encoded),
            MANIFEST_MAX_BYTES,
        )
        return {}

    return result


def extract_npm_metadata_from_artifact(artifact):
    """
    Extract name, version and manifest from an npm package tarball.

    npm tarballs are gzipped tar archives containing a ``package/package.json``
    (or ``<dir>/package.json``) entry.

    Args:
        artifact: A Pulp Artifact whose file is an npm tarball (.tgz).

    Returns:
        dict: A dictionary with ``name`` and ``version`` keys, plus ``manifest``
            holding the decoded ``package.json``.

    Raises:
        ValueError: If the tarball cannot be read or ``package.json`` is
            missing, unreadable, too large, or invalid.
    """
    try:
        with tempfile.NamedTemporaryFile(suffix=".tgz") as tmp:
            with artifact.file.open("rb") as af:
                for chunk in af.chunks():
                    tmp.write(chunk)
            tmp.flush()
            tmp.seek(0)

            with tarfile.open(fileobj=tmp, mode="r:gz") as tar:
                package_json_member = None
                for member_count, member in enumerate(tar, start=1):
                    if member_count > MAX_TAR_MEMBERS:
                        raise ValueError("npm tarball contains too many entries.")
                    parts = member.name.split("/")
                    if len(parts) == 2 and parts[-1] == "package.json" and member.isfile():
                        package_json_member = member
                        break

                if package_json_member is None:
                    raise ValueError("No package.json found in npm tarball.")
                if package_json_member.size > MAX_PACKAGE_JSON_BYTES:
                    raise ValueError(
                        "package.json in npm tarball exceeds the maximum allowed size."
                    )

                f = tar.extractfile(package_json_member)
                if f is None:
                    raise ValueError("Could not read package.json from npm tarball.")

                raw = f.read(MAX_PACKAGE_JSON_BYTES + 1)
                if len(raw) > MAX_PACKAGE_JSON_BYTES:
                    raise ValueError(
                        "package.json in npm tarball exceeds the maximum allowed size."
                    )

                package_data = json.loads(raw)
    except (tarfile.TarError, OSError, UnicodeDecodeError, json.JSONDecodeError) as e:
        raise ValueError(f"Failed to read npm tarball: {e}")

    if not isinstance(package_data, dict):
        raise ValueError("package.json in npm tarball is not a JSON object.")

    name = package_data.get("name")
    version = package_data.get("version")

    if not name or not version:
        raise ValueError(
            "package.json in npm tarball is missing required 'name' or 'version' fields."
        )

    return {"name": name, "version": version, "manifest": package_data}
